word('vendre','fr:vendre:sell','vendre','продавать','ва́(н)др',2,ex('Je suis vendeur. Je vends des livres.','Я продавец. Я продаю книги.','жё сюи ва(н)дё́р. жё ва(н) дэ ли́вр'),['Преподавать','Продавать','Лечить'],1,'Нужно сообщить о продаже книг.',[('Je vends des livres.','жё ва(н) дэ ли́вр'),('J’enseigne à l’école.','жа(н)сэнь а лэко́ль'),('Je travaille à l’hôpital.','жё травай а лопита́ль')],0)
