word('horaire','fr:horaire:work-schedule','un horaire','рабочее расписание','э(н) норэ́р',3,ex('Mon horaire : de huit heures à dix heures.','Моё рабочее расписание: с восьми до десяти часов.','мо(н) норэр: дё юи тёр а ди зё́р'),['Рабочее расписание','Профессия','Компания'],0,'Нужно выбрать запись рабочего расписания.',[('Mon métier : vendeur.','мо(н) мэтье: ва(н)дё́р'),('Mon horaire : de huit heures à dix heures.','мо(н) норэр: дё юи тёр а ди зё́р'),('Je travaille dans une entreprise.','жё травай да(н) зюн а(н)трёпри́з')],1)
word('collegue','fr:collegue:work-colleague','un collègue','коллега по работе','э(н) колэ́г',4,ex('Je travaille avec un collègue.','Я работаю с коллегой.','жё травай авэк э(н) колэ́г'),['Пациент','Друг вне рабочего контекста','Коллега по работе'],2,'Нужно сообщить о совместной работе с коллегой.',[('Je travaille avec un collègue.','жё травай авэк э(н) колэ́г'),('Je soigne des patients.','жё суань дэ пасья́(н)'),('J’aime sortir avec un ami.','жэм сортир авэк э(н) нами́')],0)
word('equipe','fr:equipe:work-team','une équipe','команда коллег','юн эки́п',4,ex('Je travaille dans une équipe.','Я работаю в команде.','жё травай да(н) зюн эки́п'),['Команда коллег','Время перерыва','Профессия'],0,'Нужно сообщить о работе в команде.',[('Je commence à huit heures.','жё кома(н)с а юи тё́р'),('Je travaille dans une équipe.','жё травай да(н) зюн эки́п'),('Mon métier : médecin.','мо(н) мэтье: мэдсэ́(н)')],1)
def cards(ids):return [wc(w) for w in ids]
