page(s,[('Место и работодатель',['Офис в этой теме — рабочее место, а не предмет мебели. Компания обозначает организацию-работодателя. Вымышленное название не требует знаний о настоящем бизнесе.'],[W['bureau']['example'],W['entreprise']['example']]),('Выбранные сочетания',['Для места и названия работодателя показаны разные сочетания. Они учатся в коротких полезных образцах без общей таблицы предлогов.'],[W['hopital']['example'],ex('Je travaille chez Nova.','Я работаю в компании Nova.','жё травай шэ но́ва')]),('Работать и посещать',['Движение к месту в определённый час не доказывает, что человек там работает. Ищите прямо названную работу.'],[ex('Je vais à l’hôpital à midi.','Я иду в больницу в полдень.','жё вэ а лопиталь а миди́')])])

