choose(s,'reading',[U],['travailler','bureau','aller','hopital','midi','entreprise'],['bureau'],'Какое место прямо связано с работой?',fr('Je travaille au bureau. Je vais à l’hôpital à midi. Je travaille dans une entreprise. Je travaille au bureau.','жё травай о бюро́. жё вэ а лопиталь а миди́. жё травай да(н) зюн а(н)трёпри́з. жё травай о бюро́.'),['Больница','Офис','Вокзал'],1,'С работой связан офис.','Больница названа как место посещения в полдень. Работа прямо указана в офисе.')
intro(s,2,'Un métier — «профессия». Mon métier : professeur. — «Моя профессия: преподаватель». Знакомые названия профессий повторяются. В нейтральном сообщении о профессии после быть в образцах нет артикля: Je suis professeur. Je suis vendeur. Enseigner — «преподавать»: J’enseigne à l’école. Vendre — «продавать»: Je vends des livres. Сохраняйте показанные личные формы и названия обязанностей; профессию не нужно угадывать только по зданию.',['metier','enseigner','vendre'],[('Un métier','э(н) мэтье́'),('Mon métier : professeur.','мо(н) мэтье: профэсё́р'),('Je suis professeur.','жё сюи профэсё́р'),('Je suis vendeur.','жё сюи ва(н)дё́р'),('Enseigner','а(н)сэньэ́'),('J’enseigne à l’école.','жа(н)сэнь а лэко́ль'),('Vendre','ва́(н)др'),('Je vends des livres.','жё ва(н) дэ ли́вр')],('Je suis professeur. J’enseigne à l’école. Je suis vendeur. Je vends des livres.','жё сюи профэсё́р. жа(н)сэнь а лэко́ль. жё сюи ва(н)дё́р. жё ва(н) дэ ли́вр.'))
pairs(s,[U],[('metier','Профессия'),('enseigner','Преподавать'),('vendre','Продавать')],'Вы различили профессию как понятие и две обязанности.','Профессия — название рода работы; преподавать и продавать обозначают разные действия.')
listen(s,[U],['professeur','enseigner','ecole','commencer','huit','heure','finir','dix'],['enseigner'],'Какую обязанность человек прямо называет?', 'Je suis professeur. J’enseigne à l’école. Je commence à huit heures. Je finis à dix heures. J’enseigne à l’école.','жё сюи профэсё́р. жа(н)сэнь а лэко́ль. жё кома(н)с а юи тё́р. жё фини а ди зё́р. жа(н)сэнь а лэко́ль.',['Продаёт книги','Лечит пациентов','Преподаёт'],2,'Человек прямо сообщает о преподавании.','В тексте названа обязанность преподавать. Продажа и лечение в этом сообщении не указаны.')
intro(s,4,'Soigner — «лечить пациентов» как обязанность врача, un patient — «пациент». Je suis médecin. Je soigne des patients. — «Я врач. Я лечу пациентов». Название врача уже знакомо; здесь добавляются действие и люди, к которым оно относится. Это описание работы, без медицинских советов и способов лечения.',['soigner','patient'],[('Soigner','суаньэ́'),('un patient','э(н) пасья́(н)'),('Je suis médecin. Je soigne des patients.','жё сюи мэдсэ́(н). жё суань дэ пасья́(н)')],('Je suis médecin. Je soigne des patients.','жё сюи мэдсэ́(н). жё суань дэ пасья́(н).'))
pairs(s,[U],[('soigner','Лечить пациентов'),('patient','Пациент'),('medecin','Врач')],'Вы различили обязанность, пациента и профессию врача.','Лечить — действие, пациент — человек, которого лечат, врач — прямо названная профессия.')
choose(s,'reading',[U],['medecin','travailler','hopital','soigner','patient','commencer','neuf','heure','finir','dix'],['medecin','soigner','patient'],'Какие профессия и обязанность прямо названы?',fr('Je suis médecin. Je travaille à l’hôpital. Je soigne des patients. Je commence à neuf heures. Je finis à dix heures.','жё сюи мэдсэ́(н). жё травай а лопита́ль. жё суань дэ пасья́(н). жё кома(н)с а нё вё́р. жё фини а ди зё́р.'),['Врач; лечит пациентов','Продавец; продаёт книги','Преподаватель; преподаёт'],0,'Названы врач и лечение пациентов.','Оба сведения даны словами. Место работы само по себе не заменяет прямо названную профессию и действие.')
grammar(fill(s,[U],['vendre','livre'],[],'Восстановите показанную личную форму «Я продаю книги».','Je ','жё',' des livres.','дэ ли́вр',[fr('vendre','ва(н)др'),fr('vends','ва(н)')],1,'Je vends des livres.','жё ва(н) дэ ли́вр.','Сохранена форма действия о себе из образца.','В сообщении о себе нужна показанная личная форма; словарное название продавать сюда не переносим.'))
order(s,[U],['professeur','enseigner','ecole'],[],'Соберите «Я преподаватель. Я преподаю в школе». Сначала профессия, затем обязанность и место.',[('Je suis','жё сюи́'),('professeur.','профэсё́р'),('J’enseigne','жа(н)сэ́нь'),('à l’école.','а лэко́ль')],'Je suis professeur. J’enseigne à l’école.','жё сюи профэсё́р. жа(н)сэнь а лэко́ль.','Получились сообщение о профессии и обязанность с местом.','Сначала поставьте профессию, затем целую личную форму преподавания и школу.')
page(s,[('Профессия в коротком сообщении',['В нейтральных образцах название профессии после быть дано без артикля. Полные словарные карточки известных профессий сохраняются с прежними артиклями и ключами.'],[ex('Je suis professeur. Je suis vendeur. Je suis médecin.','Я преподаватель. Я продавец. Я врач.','жё сюи профэсё́р. жё сюи ва(н)дё́р. жё сюи мэдсэ́(н).')]),('Обязанность',['Преподавать, продавать и лечить — разные действия. Показаны полезные личные формы без полного спряжения.'],[W['enseigner']['example'],W['vendre']['example'],W['soigner']['example']]),('Прямые сведения',['Профессия и действие названы в тексте. Не нужно угадывать профессию любого сотрудника только по учреждению, где он работает.'],[W['metier']['example']])])

