choose(s,'vocabulary',[A],['horaire','metier','entreprise'],['horaire'],'Нужно назвать рабочее расписание, а не профессию или работодателя. Что выбрать?',ru('Выберите название организации рабочего времени.'),[wc('metier'),wc('horaire'),wc('entreprise')],1,'Выбрано рабочее расписание.','Профессия описывает род работы, компания — работодателя. Нужное понятие здесь — расписание.')
choose(s,'reading',[A],['travailler','lundi','vendredi','commencer','huit','heure','et','finir','dix','faire-une-pause','neuf'],['lundi','vendredi','commencer','huit'],'В какие дни работает человек и во сколько начинает?',fr('Je travaille du lundi au vendredi. Je commence à huit heures et je finis à dix heures. Je fais une pause à neuf heures.','жё травай дю лё(н)ди о ва(н)дрэди́. жё кома(н)с а юи тёр э жё фини а ди зё́р. жё фэ юн поз а нё вё́р.'),['С понедельника по пятницу; в девять','С понедельника по пятницу; в восемь','Только в понедельник; в восемь'],1,'Работа — с понедельника по пятницу; начало в восемь.','Девять — время перерыва. Период дней не ограничивается только понедельником.')
grammar(fill(s,[A],['horaire','huit','heure','dix'],[],'Восстановите показанный промежуток часов с восьми до десяти.','Mon horaire : de huit heures ','мо(н) норэр: дё юи тё́р',' dix heures.','ди зё́р',[fr('au','о'),fr('à','а')],1,'Mon horaire : de huit heures à dix heures.','мо(н) норэр: дё юи тёр а ди зё́р.','Сохранено изученное сочетание границ времени.','Для этого промежутка часов нужна показанная форма перед десятью часами; форму из периода дней сюда не переносим.'))
order(s,[A],['travailler','lundi','vendredi','commencer','huit','heure','finir','dix'],[],'Соберите сообщение: работа с понедельника по пятницу, начало в восемь, конец в десять. Сохраните этот порядок.',[('Je travaille','жё трава́й'),('du lundi au vendredi.','дю лё(н)ди о ва(н)дрэди́'),('Je commence','жё кома́(н)с'),('à huit heures.','а юи тё́р'),('Je finis','жё фини́'),('à dix heures.','а ди зё́р')],'Je travaille du lundi au vendredi. Je commence à huit heures. Je finis à dix heures.','жё травай дю лё(н)ди о ва(н)дрэди́. жё кома(н)с а юи тё́р. жё фини а ди зё́р.','Получились дни работы, начало и окончание.','Сначала поставьте дни работы, затем начало в восемь и окончание в десять.')
page(s,[('Рабочий промежуток',['Начало и окончание работы — разные границы. Перерыв внутри промежутка не заменяет ни одну из них.'],[W['horaire']['example']]),('Дни и часы',['В выбранных образцах период дней и промежуток часов оформлены разными сочетаниями. Они даны как готовые полезные рамки.'],[ex('Je travaille du lundi au vendredi.','Я работаю с понедельника по пятницу.','жё травай дю лё(н)ди о ва(н)дрэди́'),ex('Je commence à huit heures. Je finis à dix heures.','Я начинаю в восемь. Я заканчиваю в десять.','жё кома(н)с а юи тё́р. жё фини а ди зё́р.')]),('Два условия вопроса',['Если в тексте есть два разных дня, сначала найдите нужный день, затем начало или окончание. Время другого дня не даёт ответа.'],[ex('Mardi, je commence à neuf heures.','Во вторник я начинаю в девять часов.','марди, жё кома(н)с а нё вё́р')])])

